import math

def is_power_of_5(N):
    if N <= 0:
        return False
    while N % 5 == 0:
        N //= 5
    return N == 1

N_values = [11, 15, 19, 23]
results = {}

print("--- Results for n=11, 15, 19, 23 ---")
for n in N_values:
    value = (2**n) - 3
    is_power = is_power_of_5(value)
    results[n] = {'value': value, 'is_power_of_5': is_power}

    status = "IS a power of 5" if is_power else "IS NOT a power of 5"
    print(f"n={n}: 2^{n} - 3 = {value}. {status}")

print("\nStructured Results:")
for n, data in results.items():
    print(f"n={n}: Value={data['value']}, Power_of_5={data['is_power_of_5']}")
